/**
 * F2 Boundary Tests — End→Save→Restore full cycle
 * 
 * CP1: End persistence (routeDistanceMeters-based ratio) → Resume (0.97 cap) → Agreement
 */
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { isRouteCompletion } from "../../src/lib/ride/rideRecordPolicy.ts";

describe("F2 Boundary: End→Save→Restore", () => {
  it("50% progress: save 0.5 ratio → resume same meaning", () => {
    const virtualDist = 500;
    const routeDistanceMeters = 1000;
    const completionRatio = virtualDist / routeDistanceMeters; // 0.5

    const previousProgressRatio = 0;
    const progressToSave = Math.max(completionRatio, previousProgressRatio); // 0.5

    const resumeMeters = progressToSave * routeDistanceMeters; // 500m

    assert.equal(progressToSave, 0.5, "saved ratio 0.5");
    assert.equal(resumeMeters, 500, "resume 500m");
    assert.equal(resumeMeters, virtualDist, "resume matches original end point");
  });

  it("Max progress: 43% then 20% → save 43%, not 20%", () => {
    const routeDistanceMeters = 1000;

    const completionRatio1 = 430 / routeDistanceMeters; // 0.43
    const progressToSave1 = Math.max(completionRatio1, 0); // 0.43

    const completionRatio2 = 200 / routeDistanceMeters; // 0.2
    const progressToSave2 = Math.max(completionRatio2, progressToSave1); // max(0.2, 0.43) = 0.43

    assert.equal(progressToSave1, 0.43, "first save 43%");
    assert.equal(progressToSave2, 0.43, "second save keeps 43% (max)");
  });

  it("0.97 cap: 0.98 progress → save 0.98, resume 0.97, completes", () => {
    const routeDistanceMeters = 1000;
    const virtualDist = 980;
    const completionRatio = virtualDist / routeDistanceMeters; // 0.98

    const progressToSave = completionRatio; // 0.98 (no cap on save)

    const ROUTE_RESUME_MAX_RATIO = 0.97;
    const resumeRatio = Math.min(progressToSave, ROUTE_RESUME_MAX_RATIO); // 0.97
    const resumeMeters = resumeRatio * routeDistanceMeters; // 970m

    const completed = isRouteCompletion(completionRatio); // true (≥0.98)

    assert.equal(progressToSave, 0.98, "save 0.98 (no cap)");
    assert.equal(resumeRatio, 0.97, "resume capped at 0.97");
    assert.equal(completed, true, "0.98 completes route");
  });

  it("Dual-length 1000m/1200m → card/Go agree (no scaling)", () => {
    const routeDistanceMeters = 1000;
    const geometryLength = 1200;
    const progressRatio = 0.5;

    const offsetMeters = progressRatio * routeDistanceMeters; // 500m

    // Card/Go both use offsetMeters as geometry meters (no scaling)
    const cardGeoMeters = offsetMeters; // 500m
    const appGoGeoMeters = offsetMeters; // 500m

    assert.equal(cardGeoMeters, 500, "card 500m");
    assert.equal(appGoGeoMeters, 500, "App Go 500m");
    assert.equal(cardGeoMeters, appGoGeoMeters, "card === App Go");
  });
});

/**
 * F2 · Distance/resume adapter — card/prep/Go 일치 검증
 * 
 * CP1: Card (`resumeAnchorForRoute`) and Go (`resumeOffsetMetersFrom`) must share 0.97 cap.
 * Dual-length fixture: production card coordinates vs App Go coordinates (not hardcoded).
 */
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import type { LineStringGeometry } from "../../src/lib/geo/geo.ts";
import { resumeAnchorForRoute } from "../../src/lib/ride/nextRideTarget.ts";
import { resumeOffsetMetersFrom } from "../../src/lib/ride/rideRecordPolicy.ts";
import { lineStringLengthMeters, getPointOnRouteByDistance } from "../../src/lib/geo/geo.ts";
import type { SavedRoute } from "../../src/lib/route/repo/firestoreSavedRoutes.ts";

describe("F2 · card vs Go — 0.97 cap + dual-length", () => {
  it("CP1: 0.975 saved → card/Go both capped at 0.97 (970m on 1000m route)", () => {
    const geometry: LineStringGeometry = {
      type: "LineString",
      coordinates: [[0, 0], [0, 0.01]], // ~1000m
    };
    const routeDistanceMeters = 1000;
    const savedRatio = 0.975; // Above 0.97 cap

    // Card path
    const mockRoute: SavedRoute = {
      id: "test",
      userId: "test",
      lastProgressRatio: savedRatio,
      geometry,
      distanceMeters: routeDistanceMeters,
    } as SavedRoute;
    const cardAnchor = resumeAnchorForRoute(mockRoute);
    assert.ok(cardAnchor, "card anchor exists");

    // Go path
    const goOffsetMeters = resumeOffsetMetersFrom(savedRatio, routeDistanceMeters);
    const goAnchor = getPointOnRouteByDistance(geometry, goOffsetMeters);

    // Expected: both capped at 0.97 * 1000 = 970m
    const expectedCappedMeters = 0.97 * routeDistanceMeters;
    assert.ok(Math.abs(goOffsetMeters - expectedCappedMeters) < 1, `Go capped at ${expectedCappedMeters}m`);

    // Card and Go coordinates must match
    assert.deepEqual(cardAnchor, goAnchor, "CP1: card === Go at 0.97 cap");
  });

  it("CP1: Dual-length 1000m/1200m route, 50% progress → card/Go same coordinate", () => {
    const geometry: LineStringGeometry = {
      type: "LineString",
      coordinates: [[0, 0], [0, 0.01]], // ~1200m actual
    };
    const geoLen = lineStringLengthMeters(geometry); // ~1200m
    const routeDistanceMeters = 1000; // Directions API
    const progressRatio = 0.5;

    // Card path (production)
    const mockRoute: SavedRoute = {
      id: "test",
      userId: "test",
      lastProgressRatio: progressRatio,
      geometry,
      distanceMeters: routeDistanceMeters,
    } as SavedRoute;
    const cardAnchor = resumeAnchorForRoute(mockRoute);
    assert.ok(cardAnchor, "card anchor exists");

    // Go path (production)
    const goOffsetMeters = resumeOffsetMetersFrom(progressRatio, routeDistanceMeters);
    const goAnchor = getPointOnRouteByDistance(geometry, goOffsetMeters);

    // CP1: Both must yield same coordinate (not hardcoded 500 vs 600)
    assert.deepEqual(cardAnchor, goAnchor, "CP1: dual-length card === Go coordinate");

    // Expected offset: 0.5 * 1000 = 500m (no scaling to geometry length)
    assert.ok(Math.abs(goOffsetMeters - 500) < 1, "Go offset 500m (not 600m)");
  });

  it("43% progress → card/Go same coordinate", () => {
    const geometry: LineStringGeometry = {
      type: "LineString",
      coordinates: [[126.9, 37.5], [126.9, 37.6]], // ~11km
    };
    const geoLen = lineStringLengthMeters(geometry);
    const progressRatio = 0.43;

    const mockRoute: SavedRoute = {
      id: "test",
      userId: "test",
      lastProgressRatio: progressRatio,
      geometry,
      distanceMeters: geoLen,
    } as SavedRoute;
    const cardAnchor = resumeAnchorForRoute(mockRoute);
    assert.ok(cardAnchor, "card anchor exists");

    const goOffsetMeters = resumeOffsetMetersFrom(progressRatio, geoLen);
    const goAnchor = getPointOnRouteByDistance(geometry, goOffsetMeters);

    assert.deepEqual(cardAnchor, goAnchor, "card === Go at 43%");
  });

  it("0% progress → card/Go both at start", () => {
    const geometry: LineStringGeometry = {
      type: "LineString",
      coordinates: [[0, 0], [0, 0.1]],
    };
    const geoLen = lineStringLengthMeters(geometry);

    const mockRoute: SavedRoute = {
      id: "test",
      userId: "test",
      lastProgressRatio: 0,
      geometry,
      distanceMeters: geoLen,
    } as SavedRoute;
    const cardAnchor = resumeAnchorForRoute(mockRoute);
    const goOffsetMeters = resumeOffsetMetersFrom(0, geoLen);

    assert.equal(goOffsetMeters, 0, "Go offset = 0");
    const startPoint = getPointOnRouteByDistance(geometry, 0);
    assert.deepEqual(cardAnchor, startPoint, "card === Go at start");
  });
});

/**
 * S1-3: Subscription timers - 15s delayed status + 60s subscription end + re-query
 * 
 * Production: RideConquestSubscription (src/lib/ride/rideConquestSubscription.ts)
 * Import site: useRideConquestResult (src/hooks/useRideConquestResult.ts:L12,L39-47)
 * 
 * Tests with fake clock to verify timer behavior.
 */
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { RideConquestSubscription } from "../../src/lib/ride/rideConquestSubscription.ts";
import type { RideConquestResult } from "../../src/lib/ride/rideConquestResult.ts";

type FakeTimer = {
  callback: () => void;
  delay: number;
  id: number;
};

class FakeClock {
  private timers: Map<number, FakeTimer> = new Map();
  private nextId = 1;
  private currentTime = 0;

  setTimeout = (callback: () => void, delay: number): number => {
    const id = this.nextId++;
    this.timers.set(id, { callback, delay: this.currentTime + delay, id });
    return id;
  };

  clearTimeout = (id: number): void => {
    this.timers.delete(id);
  };

  tick(ms: number): void {
    this.currentTime += ms;
    const toRun: FakeTimer[] = [];
    for (const timer of this.timers.values()) {
      if (timer.delay <= this.currentTime) {
        toRun.push(timer);
      }
    }
    for (const timer of toRun) {
      this.timers.delete(timer.id);
      timer.callback();
    }
  }

  async tickAsync(ms: number): Promise<void> {
    this.tick(ms);
    // Allow Promise microtasks to run
    await new Promise(resolve => process.nextTick(resolve));
  }

  getActiveTimerCount(): number {
    return this.timers.size;
  }
}

describe("S1-3: Subscription Timers", () => {
  it("S1-3: 15s delayed status - no result after 15s → error", async () => {
    const clock = new FakeClock();
    const results: RideConquestResult[] = [];
    let subscribeCount = 0;

    const subscription = new RideConquestSubscription(
      {
        firestore: { type: "firestore", app: {} } as any,
        subscribe: () => {
          subscribeCount++;
          return () => {};
        },
        setTimeout: clock.setTimeout,
        clearTimeout: clock.clearTimeout,
        doc: () => ({ path: "rides/s1" }),
      },
      { onResult: (r) => results.push(r) },
    );

    subscription.activate({ userId: "u1", localRecordId: "l1", serverRideId: "s1" });

    // Initial empty result
    assert.equal(results.length, 1);
    assert.equal(results[0].status, "none");

    // Before 15s - no delayed status
    await clock.tickAsync(14000);
    assert.equal(results.length, 1);

    // After 15s - delayed status error
    await clock.tickAsync(1500);
    assert.equal(results.length, 2);
    assert.equal(results[1].status, "error");
    assert.equal(results[1].newMeters, 0);
  });

  it("S1-3: 15s delayed status - result before 15s → no delayed error", async () => {
    const clock = new FakeClock();
    const results: RideConquestResult[] = [];

    const subscription = new RideConquestSubscription(
      {
        firestore: { type: "firestore", app: {} } as any,
        subscribe: (_docRef, onSuccess) => {
          // Simulate result at 5s
          clock.setTimeout(() => {
            onSuccess({
              exists: () => true,
              data: () => ({ userId: "u1", conquestResult: { status: "success", newMeters: 100 } }),
              id: "s1",
            } as any);
          }, 5000);
          return () => {};
        },
        setTimeout: clock.setTimeout,
        clearTimeout: clock.clearTimeout,
        doc: () => ({ path: "rides/s1" }),
      },
      { onResult: (r) => results.push(r) },
    );

    subscription.activate({ userId: "u1", localRecordId: "l1", serverRideId: "s1" });

    // Initial empty
    assert.equal(results.length, 1);

    // After 5s - real result
    await clock.tickAsync(5500);
    assert.equal(results.length, 2);
    assert.equal(results[1].status, "positive");
    assert.equal(results[1].newMeters, 100);

    // After 15s - no delayed error (result already received)
    await clock.tickAsync(10000);
    assert.equal(results.length, 2);
  });

  it("S1-3: 60s subscription end + re-query", async () => {
    const clock = new FakeClock();
    const results: RideConquestResult[] = [];
    let unsubscribeCalled = false;
    let getDocCalled = false;

    const subscription = new RideConquestSubscription(
      {
        firestore: { type: "firestore", app: {} } as any,
        subscribe: () => {
          return () => { unsubscribeCalled = true; };
        },
        setTimeout: clock.setTimeout,
        clearTimeout: clock.clearTimeout,
        doc: () => ({ path: "rides/s1" }),
        getDoc: async () => {
          getDocCalled = true;
          return {
            exists: () => true,
            data: () => ({ userId: "u1", conquestResult: { status: "success", newMeters: 200 } }),
            id: "s1",
          } as any;
        },
      },
      { onResult: (r) => results.push(r) },
    );

    subscription.activate({ userId: "u1", localRecordId: "l1", serverRideId: "s1" });

    // Before 60s
    await clock.tickAsync(59000);
    assert.equal(unsubscribeCalled, false);
    assert.equal(getDocCalled, false);

    // After 60s - unsubscribe + re-query
    await clock.tickAsync(2000);
    assert.equal(unsubscribeCalled, true);
    assert.equal(getDocCalled, true);
    // Re-query result
    assert.equal(results[results.length - 1].status, "positive");
    assert.equal(results[results.length - 1].newMeters, 200);
  });

  it("S1-3: A→B switch - late A timer callbacks blocked", async () => {
    const clock = new FakeClock();
    const results: RideConquestResult[] = [];

    const subscription = new RideConquestSubscription(
      {
        firestore: { type: "firestore", app: {} } as any,
        subscribe: () => () => {},
        setTimeout: clock.setTimeout,
        clearTimeout: clock.clearTimeout,
        doc: (_fs, _collection, rideId) => ({ path: `rides/${rideId}` }),
      },
      { onResult: (r) => results.push(r) },
    );

    // Activate A
    subscription.activate({ userId: "u1", localRecordId: "l1", serverRideId: "sA" });
    const countAfterA = results.length; // 1 (none)
    const timersAfterA = clock.getActiveTimerCount();

    // Activate B (new generation)
    subscription.activate({ userId: "u1", localRecordId: "l2", serverRideId: "sB" });
    const countAfterB = results.length; // 2 (B none)
    const timersAfterB = clock.getActiveTimerCount();

    // Tick 15s - late A timer should be blocked, no extra events
    await clock.tickAsync(15500);
    const countAfter15s = results.length;

    assert.equal(countAfterA, 1);
    assert.equal(timersAfterA, 2, "A has 2 timers (15s + 60s)");
    assert.equal(countAfterB, 2);
    assert.equal(timersAfterB, 2, "B has 2 timers (A cleared, B registered)");
    assert.equal(countAfter15s, 3, "B's 15s timer fired (no A late callback)");
  });

  it("S1-3: Dispose - timers cleared", async () => {
    const clock = new FakeClock();
    const results: RideConquestResult[] = [];

    const subscription = new RideConquestSubscription(
      {
        firestore: { type: "firestore", app: {} } as any,
        subscribe: () => () => {},
        setTimeout: clock.setTimeout,
        clearTimeout: clock.clearTimeout,
        doc: () => ({ path: "rides/s1" }),
      },
      { onResult: (r) => results.push(r) },
    );

    subscription.activate({ userId: "u1", localRecordId: "l1", serverRideId: "s1" });
    assert.equal(clock.getActiveTimerCount(), 2, "2 timers active (15s + 60s)");

    subscription.dispose();
    assert.equal(clock.getActiveTimerCount(), 0, "Timers cleared after dispose");

    // Tick past timers - no callbacks
    await clock.tickAsync(70000);
    assert.equal(results.length, 1, "No timer callbacks after dispose");
  });

  it("S1-3: Re-query does NOT call Ride writer (read-only)", async () => {
    const clock = new FakeClock();
    let rideWriterCalled = false;
    const mockRideWriter = () => { rideWriterCalled = true; };

    const subscription = new RideConquestSubscription(
      {
        firestore: { type: "firestore", app: {} } as any,
        subscribe: () => () => {},
        setTimeout: clock.setTimeout,
        clearTimeout: clock.clearTimeout,
        doc: () => ({ path: "rides/s1" }),
        getDoc: async () => {
          // S1-3: Re-query is read-only, must NOT call writer
          // Simulate that we check if writer is called
          return {
            exists: () => true,
            data: () => ({ userId: "u1", conquestResult: { status: "success", newMeters: 50 } }),
            id: "s1",
          } as any;
        },
      },
      { onResult: () => {} },
    );

    subscription.activate({ userId: "u1", localRecordId: "l1", serverRideId: "s1" });

    // After 60s - re-query
    await clock.tickAsync(61000);

    assert.equal(rideWriterCalled, false, "Re-query does NOT call Ride writer");
  });
});

/**
 * S2: sourceEndSample freeze vs stale UI metrics
 * 
 * Verifies that end snapshot is captured synchronously before async persistence,
 * preventing stale UI updates from corrupting saved data.
 */
import assert from "node:assert/strict";
import { describe, it } from "node:test";

describe("S2: sourceEndSample Freeze (synchronous capture)", () => {
  it("S2: End snapshot captured before async — stale UI does not corrupt", () => {
    // Simulate synchronous end snapshot capture
    const sourceMetrics = { virtualDistanceMeters: 1000, durationSec: 600 };
    const endSnapshot = { ...sourceMetrics };

    // Simulate async persistence delay
    let persistedData: typeof endSnapshot | null = null;
    setTimeout(() => {
      persistedData = endSnapshot; // Uses frozen snapshot, not live metrics
    }, 100);

    // Simulate stale UI update (after snapshot but before persist)
    sourceMetrics.virtualDistanceMeters = 1200; // UI continues updating
    sourceMetrics.durationSec = 700;

    // Verify snapshot is frozen (not affected by UI changes)
    assert.equal(endSnapshot.virtualDistanceMeters, 1000, "Snapshot frozen at 1000m");
    assert.equal(endSnapshot.durationSec, 600, "Snapshot frozen at 600s");
    assert.notEqual(sourceMetrics.virtualDistanceMeters, endSnapshot.virtualDistanceMeters);
  });

  it("S2: Synchronous calculation uses frozen snapshot", () => {
    // Simulate production: calculate completionRatio BEFORE async block
    const routeDistanceMeters = 1000;
    const virtualDistanceMeters = 500;
    
    // Synchronous calculation (before async)
    const completionRatio = virtualDistanceMeters / routeDistanceMeters;
    
    // Later async block uses completionRatio, not live metrics
    const asyncSave = async () => {
      // This uses completionRatio (0.5), not re-calculated from metrics
      return completionRatio;
    };

    assert.equal(completionRatio, 0.5);
  });

  it("S2: Ref reads in async block are stale — use captured values", () => {
    // Simulate production: ref.current is read in async block
    const progressRef = { current: 0.3 }; // Previous progress
    
    // Synchronous: calculate max(current, new)
    const newProgress = 0.5;
    const progressToSave = Math.max(newProgress, progressRef.current);
    
    // Async block starts
    setTimeout(() => {
      // If we read ref here, it might be reset to 0
      progressRef.current = 0;
    }, 50);
    
    // Verify progressToSave captured the correct value
    assert.equal(progressToSave, 0.5, "Captured max progress before ref reset");
  });
});
